class Solution {
public:
    int minimumOperations(std::vector<int>& nums, int start, int goal) {
        std::vector<bool> visited(1001, false);
        std::queue<std::pair<int, int>> q;
        q.push({start, 0});
        if (start >= 0 && start <= 1000) visited[start] = true;

        while (!q.empty()) {
            auto [curr, steps] = q.front();
            q.pop();

            if (curr == goal) return steps;

            for (int num : nums) {
                int nextVals[3] = {curr + num, curr - num, curr ^ num};
                for (int nxt : nextVals) {
                    if (nxt == goal) return steps + 1;
                    if (nxt >= 0 && nxt <= 1000 && !visited[nxt]) {
                        visited[nxt] = true;
                        q.push({nxt, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
};

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int minimumOperations(int[] nums, int start, int goal) {
        boolean[] visited = new boolean[1001];
        Queue<int[]> q = new ArrayDeque<>();
        q.offer(new int[]{start, 0});
        if (start >= 0 && start <= 1000) visited[start] = true;

        while (!q.isEmpty()) {
            int[] top = q.poll();
            int curr = top[0];
            int steps = top[1];

            if (curr == goal) return steps;

            for (int num : nums) {
                int[] nxtVals = new int[]{curr + num, curr - num, curr ^ num};
                for (int nxt : nxtVals) {
                    if (nxt == goal) return steps + 1;
                    if (nxt >= 0 && nxt <= 1000 && !visited[nxt]) {
                        visited[nxt] = true;
                        q.offer(new int[]{nxt, steps + 1});
                    }
                }
            }
        }
        return -1;
    }
}

